style.css:
@-moz-document url-prefix("https://ocean.orange-business.com") {
.menu-bouton-x > .dropbtn, 
button,
input[type=submit],
.dt-btn:not(.btn-hover-off) {
	border-radius: 6px !important;
  background: none;
  border-color: #0d8dc9 !important;
  background-color: #0d8dc9 !important;
}

div[class*="box-lien"] > div *[class*="lienappel"] {
  background: none;
  border-color: #0d8dc9 !important;
  background-color: #0d8dc9 !important;
  color: #ffffff !important;
}

.uvc-headings-line {
  border-color: #0d8dc9 !important;
}

.dropdown-content a:hover, 
.dropdown-content a:hover > p, 
li > a:hover, 
.rollover-icon, 
a[class*="link-active"],
.footer a:hover,
a:hover {
  	color: #0d8dc9 !important;
}

.dropdown .dropbtn:hover,  .dropbtn:hover {
  	color: #0d8dc9 !important;
  	border-color: #0d8dc9;
}

button > span {
  background: none;
}

div.logo-container-custom img[class*="orange"] {
	visibility: hidden !important;
}
div.logo-container-custom-2 > a {
     position: absolute;
    left: 50px;
    top: 32px;
}
div.logo-container-custom-2:before {
  content: "Toto";
}

.scroll-top {
  background-color: #0d8dc9 !important;
}
}
